// O espelho: o que existe HOJE dentro do Chatwoot, para o LiveOps
// desenhar. Nada e criado aqui — macro e resposta pronta nascem no
// Chatwoot (Configuracoes > Macros / Respostas Prontas). Aqui so se le.

// A macro EXECUTA acoes no Chatwoot (mandar mensagem, etiquetar, resolver).
// E o que o botao PIX da barra lateral faz. Precisa do id para disparar.
let macrosBrutas = [];
try {
  const r = $('Listar macros').first().json;
  macrosBrutas = Array.isArray(r) ? r : (r.payload || r.data || []);
} catch (e) {}

// A resposta pronta e so TEXTO: o "/" do Chatwoot escreve no campo.
// Nao executa nada sozinha — por isso no LiveOps ela entra no grupo de
// escrever, junto dos templates.
let prontasBrutas = [];
try {
  const r = $('Listar respostas prontas').first().json;
  prontasBrutas = Array.isArray(r) ? r : (r.payload || r.data || []);
} catch (e) {}

const macros = macrosBrutas.filter(m => m && m.id).map(m => ({
  id: String(m.id),
  nome: String(m.name || 'Macro ' + m.id),
  visibilidade: String(m.visibility || ''),
  passos: Array.isArray(m.actions) ? m.actions.length : 0,
}));

const prontas = prontasBrutas.filter(c => c && c.short_code).map(c => ({
  id: String(c.id || ''),
  atalho: String(c.short_code || ''),
  texto: String(c.content || '').slice(0, 4000),
}));

return [{ json: { macros, prontas, em: Date.now() } }];

// Vem do WhatsLive: {conv:'cw_3383', macroId:'7', macroNome:'PIX', autor:'CM'}
const b = $json.body || $json;
const conv = String(b.conv || '');
const num = conv.replace(/^cw_/, '');
const macroId = String(b.macroId || '');
if (!/^\d+$/.test(num) || !/^\d+$/.test(macroId)) return [];
return [{ json: {
  convNum: num,
  convId: conv,
  macroId,
  macroNome: String(b.macroNome || 'macro').slice(0, 80),
  autor: String(b.autor || '').trim() || '?',
} }];

// Pegadinha do Chatwoot: a URL da conversa usa o display_id (3383), mas
// executar macro pede o id INTERNO. O GET acima devolve os dois — aqui se
// escolhe o certo, senao a macro roda na conversa de outra pessoa.
const p = $('Preparar disparo').first().json;
const c = $json || {};
const interno = c.id || (c.payload && c.payload.id);
if (!interno) throw new Error('Chatwoot nao devolveu o id interno da conversa ' + p.convNum);
return [{ json: Object.assign({}, p, { convInterno: String(interno) }) }];

// A macro age dentro do Chatwoot: o que ela mandar ao cliente volta pelo
// webhook de sempre e vira balao normal. Aqui so fica o RASTRO de quem
// apertou o botao — nota interna, o cliente nao ve.
const p = $('Id interno da conversa').first().json;
const ts = Date.now();
return [{ json: {
  convId: p.convId,
  msgId: 'lm' + ts,
  conv: { id: p.convId, ultima: '⚡ ' + p.macroNome, deUltima: 'agente', ts },
  msg:  { texto: '⚡ Macro "' + p.macroNome + '" executada no Chatwoot', de: 'nota', autor: p.autor, ts },
} }];
